const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 u_resolution;
	uniform vec2 u_mouse;
	uniform float u_time;
	uniform sampler2D tex0;
	uniform bool u_mouseispressed;


	varying vec2 vTexCoord;

	float rand(vec2 c){
		return fract(sin(dot(c.xy ,vec2(12.9898,78.233))) * 43758.5453);
	}

	mat2 rotate2d(float _angle){
    return mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle));
	}

	//	Classic Perlin 3D Noise 
	//	by Stefan Gustavson
	//
	vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
	vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}
	vec3 fade(vec3 t) {return t*t*t*(t*(t*6.0-15.0)+10.0);}

	float cnoise(vec3 P){
		vec3 Pi0 = floor(P); // Integer part for indexing
		vec3 Pi1 = Pi0 + vec3(1.0); // Integer part + 1
		Pi0 = mod(Pi0, 289.0);
		Pi1 = mod(Pi1, 289.0);
		vec3 Pf0 = fract(P); // Fractional part for interpolation
		vec3 Pf1 = Pf0 - vec3(1.0); // Fractional part - 1.0
		vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
		vec4 iy = vec4(Pi0.yy, Pi1.yy);
		vec4 iz0 = Pi0.zzzz;
		vec4 iz1 = Pi1.zzzz;

		vec4 ixy = permute(permute(ix) + iy);
		vec4 ixy0 = permute(ixy + iz0);
		vec4 ixy1 = permute(ixy + iz1);

		vec4 gx0 = ixy0 / 7.0;
		vec4 gy0 = fract(floor(gx0) / 7.0) - 0.5;
		gx0 = fract(gx0);
		vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
		vec4 sz0 = step(gz0, vec4(0.0));
		gx0 -= sz0 * (step(0.0, gx0) - 0.5);
		gy0 -= sz0 * (step(0.0, gy0) - 0.5);

		vec4 gx1 = ixy1 / 7.0;
		vec4 gy1 = fract(floor(gx1) / 7.0) - 0.5;
		gx1 = fract(gx1);
		vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
		vec4 sz1 = step(gz1, vec4(0.0));
		gx1 -= sz1 * (step(0.0, gx1) - 0.5);
		gy1 -= sz1 * (step(0.0, gy1) - 0.5);

		vec3 g000 = vec3(gx0.x,gy0.x,gz0.x);
		vec3 g100 = vec3(gx0.y,gy0.y,gz0.y);
		vec3 g010 = vec3(gx0.z,gy0.z,gz0.z);
		vec3 g110 = vec3(gx0.w,gy0.w,gz0.w);
		vec3 g001 = vec3(gx1.x,gy1.x,gz1.x);
		vec3 g101 = vec3(gx1.y,gy1.y,gz1.y);
		vec3 g011 = vec3(gx1.z,gy1.z,gz1.z);
		vec3 g111 = vec3(gx1.w,gy1.w,gz1.w);

		vec4 norm0 = taylorInvSqrt(vec4(dot(g000, g000), dot(g010, g010), dot(g100, g100), dot(g110, g110)));
		g000 *= norm0.x;
		g010 *= norm0.y;
		g100 *= norm0.z;
		g110 *= norm0.w;
		vec4 norm1 = taylorInvSqrt(vec4(dot(g001, g001), dot(g011, g011), dot(g101, g101), dot(g111, g111)));
		g001 *= norm1.x;
		g011 *= norm1.y;
		g101 *= norm1.z;
		g111 *= norm1.w;

		float n000 = dot(g000, Pf0);
		float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
		float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z));
		float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
		float n001 = dot(g001, vec3(Pf0.xy, Pf1.z));
		float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
		float n011 = dot(g011, vec3(Pf0.x, Pf1.yz));
		float n111 = dot(g111, Pf1);

		vec3 fade_xyz = fade(Pf0);
		vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
		vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
		float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x); 
		return 2.2 * n_xyz;
	}

	vec2 random2( vec2 p ) {
			return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);
	}


	void main(){
		vec2 st = vTexCoord.xy /u_resolution.xy;
		st.y = 1.0 - st.y;
		vec3 color = vec3(0.);

		//add translate to last current flame pos
		st.y+=0.01+sin(u_time)*0.001;
		st.x+=cos(u_time+u_mouse.x)*0.001;

		//add some different size noise distort the sampling space
		st += cnoise(vec3(st*500.,u_time*9.+u_mouse.x*5.)) *0.001;
		st += cnoise(vec3(st*20.,u_time*5.+u_mouse.y*3.))*0.005;
		st += cnoise(vec3(st*5.,u_time*2.+u_mouse.y*5.))*0.01;

		st += cnoise(vec3(st*10.,u_time*12.))*0.001;


		float d = distance(u_mouse,st);
		//caculate the last texture point
		vec4 tex = texture2D(tex0,st);


		// for(float i=-0.01;i<=0.01;i+=0.01){
		// 	for(float o=-0.01;o<=0.01;o+=0.01){
		// 		if (i!=0. && o!=0.){
		// 			color += texture2D(tex0,st+vec2(i,o)).rgb/9.;
		// 		}
		// 	}
		// }
		// color.r*=0.99;
		// color.g*=0.99;
		// color.b*=0.99;


		//generate tiles of flame generating point
		float copyCount  = 5.;
		vec2 f_st =floor(st*copyCount)+vec2(0.0,0.2);
		// f_st.y+=sin(f_st.x*500.)/10.;

		//caculate distance between current pos and flame gen point
		d = distance(f_st+0.5,st*copyCount)*0.3;

		//set last frame rgb with specific varying keeping ratio
		color.r+=tex.r*(0.2+sin(u_time*1.+st.x*10.+st.y*5.)*0.1)/pow(d,0.6);	
		color.g+=tex.g*(0.25+sin(u_time*0.5+st.y*5.)*0.1)/pow(d,0.5);		
		color.b+=tex.b*(0.25+sin(u_time*0.2+st.x+st.y)*0.1)/pow(d,0.35+sin(u_time/5.+0.5+st.y*2.)*0.1);	

		if (u_mouseispressed){
			//add new current flame with glowing using sidderent range of smooth step
			color+= smoothstep(0.03+sin(u_time*2.+st.x*10.)*0.02,0.0,d)/7.
							+smoothstep(0.1+sin(u_time*3.+st.y*10.)*0.04,0.,d)/35.
							+smoothstep(0.5+sin(u_time*10.+st.x*10.)*0.05,0.,d)/45.
							+smoothstep(0.9+sin(u_time*3.+st.y*5.)*0.09,0.,d)/60.;
		}

		//add some noise texture to current color
		color*=cnoise(vec3(st*500.,u_time*3.))*0.001+0.999;
		color*=cnoise(vec3(st*100.,u_time*3.))*0.01+0.99;
		color*=cnoise(vec3(st*5.,u_time*3.))*0.1+0.9;


		gl_FragColor= vec4(color,1.0);
	}
`



